mapper.select:
SELECT
IFNULL(SUM(abnormal_amount), 0) AS totalAbnormalAmount,
COUNT(1) AS abnormalOrderCount,
SUM(CASE WHEN disposal_status = '已处置' THEN 1 ELSE 0 END) AS disposedCount,
SUM(CASE WHEN disposal_result = '已纠错' THEN 1 ELSE 0 END) AS correctedCount
FROM park_charge_abnormal
WHERE deleted = 0

    AND abnormal_time >= #{req.startTime}


    AND abnormal_time <= #{req.endTime}


    AND region_full_code LIKE CONCAT(#{req.regionFullCode}, '%')


    AND abnormal_type = #{req.abnormalType}


    AND disposal_status = #{req.disposalStatus}


    AND order_no = #{req.orderNo}


    AND car_number = #{req.carNumber}


    AND abnormal_amount >= #{req.minAmount}


    AND abnormal_amount <= #{req.maxAmount}
